### Pattern Description

This pattern establishes comprehensive isolation testing using multiple techniques:

**Technique 1: Fault Injection Testing**

Inject failures into extensions and verify isolation holds:

```csharp
public class FaultInjectionTests
{
    [Fact]
    public async Task ExtensionException_DoesNotAffectOtherTenants()
    {
        // Arrange: Create test with two tenants
        var testHost = CreateMultiTenantTestHost();

        // Configure extension for Tenant A to throw exception
        testHost.ConfigureExtension("TenantA", "TexasClaimProcessor",
            config => config.InjectFault(new InvalidOperationException("Simulated failure")));

        // Act: Process claims for both tenants
        var taskA = testHost.ProcessClaimAsync("TenantA", CreateTestClaim());
        var taskB = testHost.ProcessClaimAsync("TenantB", CreateTestClaim());

        // Assert: Tenant A fails, but Tenant B succeeds
        await Assert.ThrowsAsync<InvalidOperationException>(() => taskA);
        var resultB = await taskB;
        Assert.True(resultB.Success, "Tenant B should not be affected by Tenant A failure");
    }
}
```

**Technique 2: Resource Limit Validation**

Enforce and test resource limits:

```csharp
[Fact]
public async Task Extension_CannotExceedMemoryLimit()
{
    var limiter = new ResourceLimiter
    {
        MaxMemoryMB = 100,
        MaxExecutionTimeSeconds = 5
    };

    using var testHost = CreateTestHost(limiter);

    // Extension that tries to allocate 500MB
    var extension = CreateMemoryIntensiveExtension();

    // Should be terminated before exhausting memory
    await Assert.ThrowsAsync<ResourceLimitExceededException>(
        () => testHost.ExecuteExtensionAsync(extension));

    // Verify process still healthy
    Assert.True(testHost.IsHealthy());
}
```

**Technique 3: Cross-Tenant Access Detection**

Verify extensions cannot access other tenant data:

```csharp
[Fact]
public async Task Extension_CannotAccessOtherTenantData()
{
    var testHost = CreateMultiTenantTestHost();

    // Setup: Tenant A has 100 claims, Tenant B has 50 claims
    await testHost.SeedTenantDataAsync("TenantA", claims: 100);
    await testHost.SeedTenantDataAsync("TenantB", claims: 50);

    // Act: Extension for Tenant A tries to query all claims
    var extension = testHost.LoadExtension("TenantA", "MaliciousExtension");
    var claims = await extension.GetAllClaimsAsync();

    // Assert: Should only see Tenant A's claims
    Assert.Equal(100, claims.Count);
    Assert.All(claims, c => Assert.Equal("TenantA", c.TenantId));
}
```

**Technique 4: Chaos Engineering**

Simulate realistic failure scenarios:

```csharp
public class ChaosTests
{
    [Fact]
    public async Task System_ResilientToRandomExtensionFailures()
    {
        var chaosEngine = new ChaosEngine()
            .WithFailureRate(0.10) // 10% of extension calls fail
            .WithFailureTypes(typeof(TimeoutException), typeof(InvalidOperationException))
            .WithRandomLatency(min: 10ms, max: 500ms);

        using var testHost = CreateTestHost(chaosEngine);

        // Execute 1000 operations across 10 tenants
        var results = new List<OperationResult>();
        for (int i = 0; i < 1000; i++)
        {
            var tenant = $"Tenant{i % 10}";
            var result = await testHost.ProcessClaimAsync(tenant, CreateTestClaim());
            results.Add(result);
        }

        // Assert: ~90% success rate, no cascading failures
        var successRate = results.Count(r => r.Success) / (double)results.Count;
        Assert.InRange(successRate, 0.85, 0.95);

        // All tenants should have processed some claims successfully
        for (int i = 0; i < 10; i++)
        {
            var tenantResults = results.Where(r => r.TenantId == $"Tenant{i}");
            Assert.True(tenantResults.Any(r => r.Success),
                $"Tenant{i} should have some successful operations");
        }
    }
}
```

**Technique 5: Containment Verification**

Test exceptions and errors are properly contained:

```csharp
[Fact]
public async Task ExtensionCrash_DoesNotCrashProcess()
{
    var testHost = CreateTestHost();

    // Extension with fatal error
    var crashingExtension = CreateCrashingExtension();

    // Execute extension
    var result = await testHost.ExecuteWithContainmentAsync(crashingExtension);

    // Assert: Extension failed but process survived
    Assert.False(result.Success);
    Assert.Contains("Extension crashed", result.ErrorMessage);
    Assert.True(testHost.IsProcessAlive());
    Assert.True(testHost.CanProcessNewRequests());
}
```

**Technique 6: Tenant Context Integrity**

Verify tenant context cannot be manipulated:

```csharp
[Fact]
public async Task Extension_CannotModifyTenantContext()
{
    var testHost = CreateMultiTenantTestHost();

    // Extension attempts to change tenant context
    var maliciousExtension = new MaliciousExtension
    {
        OnExecute = (context) =>
        {
            // Try to escalate to different tenant
            context.TenantId = "AdminTenant";
            return Task.CompletedTask;
        }
    };

    // Execute as TenantA
    using var scope = testHost.CreateTenantScope("TenantA");
    await scope.ExecuteExtensionAsync(maliciousExtension);

    // Assert: Tenant context unchanged
    Assert.Equal("TenantA", scope.GetCurrentTenantId());
}
```

