#### Phase 1: Isolation Test Framework

1. **Create Multi-Tenant Test Host**:
   ```csharp
   public class MultiTenantTestHost : IDisposable
   {
       private readonly Dictionary<string, TenantScope> _tenantScopes = new();
       private readonly IServiceProvider _serviceProvider;
       private readonly ResourceMonitor _resourceMonitor;

       public MultiTenantTestHost()
       {
           var services = new ServiceCollection();
           ConfigureServices(services);
           _serviceProvider = services.BuildServiceProvider();
           _resourceMonitor = new ResourceMonitor();
       }

       public TenantScope CreateTenantScope(string tenantId)
       {
           var scope = new TenantScope(tenantId, _serviceProvider, _resourceMonitor);
           _tenantScopes[tenantId] = scope;
           return scope;
       }

       public async Task<ClaimResult> ProcessClaimAsync(string tenantId, Claim claim)
       {
           using var scope = CreateTenantScope(tenantId);
           return await scope.ProcessClaimAsync(claim);
       }

       public async Task SeedTenantDataAsync(string tenantId, int claims = 0, int providers = 0)
       {
           using var scope = CreateTenantScope(tenantId);
           await scope.SeedDataAsync(claims, providers);
       }
   }

   public class TenantScope : IDisposable
   {
       private readonly string _tenantId;
       private readonly IServiceScope _scope;
       private readonly ITenantContext _tenantContext;
       private readonly ResourceMonitor _resourceMonitor;

       public TenantScope(string tenantId, IServiceProvider services, ResourceMonitor monitor)
       {
           _tenantId = tenantId;
           _scope = services.CreateScope();
           _tenantContext = _scope.ServiceProvider.GetRequiredService<ITenantContext>();
           _tenantContext.SetTenant(tenantId);
           _resourceMonitor = monitor;
           _resourceMonitor.StartTracking(tenantId);
       }

       public async Task<TResult> ExecuteWithIsolationAsync<TResult>(
           Func<Task<TResult>> action,
           ResourceLimits limits = null)
       {
           try
           {
               using var cts = new CancellationTokenSource(limits?.TimeoutMs ?? 5000);
               return await action();
           }
           catch (Exception ex)
           {
               // Log but contain exception
               _resourceMonitor.RecordException(_tenantId, ex);
               throw;
           }
       }

       public void Dispose()
       {
           _resourceMonitor.StopTracking(_tenantId);
           _scope.Dispose();
       }
   }
   ```

2. **Implement Resource Monitor**:
   ```csharp
   public class ResourceMonitor
   {
       private readonly ConcurrentDictionary<string, ResourceUsage> _usage = new();

       public void StartTracking(string tenantId)
       {
           _usage[tenantId] = new ResourceUsage
           {
               TenantId = tenantId,
               StartTime = DateTime.UtcNow,
               StartMemory = GC.GetTotalMemory(false)
           };
       }

       public void StopTracking(string tenantId)
       {
           if (_usage.TryGetValue(tenantId, out var usage))
           {
               usage.EndTime = DateTime.UtcNow;
               usage.EndMemory = GC.GetTotalMemory(false);
               usage.Duration = usage.EndTime - usage.StartTime;
               usage.MemoryDelta = usage.EndMemory - usage.StartMemory;
           }
       }

       public ResourceUsageReport GetReport()
       {
           return new ResourceUsageReport
           {
               TenantMetrics = _usage.Values.ToList(),
               TotalMemoryUsed = _usage.Values.Sum(u => u.MemoryDelta),
               MaxMemoryByTenant = _usage.Values.Max(u => u.MemoryDelta)
           };
       }
   }
   ```

