#### Phase 2: Fault Injection Testing

3. **Create Fault Injector**:
   ```csharp
   public class FaultInjector
   {
       private readonly Dictionary<string, FaultConfiguration> _faults = new();

       public void ConfigureFault(string extensionName, FaultConfiguration config)
       {
           _faults[extensionName] = config;
       }

       public async Task<TResult> ExecuteWithFaultsAsync<TResult>(
           string extensionName,
           Func<Task<TResult>> action)
       {
           if (_faults.TryGetValue(extensionName, out var fault))
           {
               // Inject delay
               if (fault.DelayMs > 0)
                   await Task.Delay(fault.DelayMs);

               // Inject exception
               if (fault.Exception != null && Random.Shared.NextDouble() < fault.FailureRate)
                   throw fault.Exception;

               // Inject resource consumption
               if (fault.AllocateMemoryMB > 0)
                   _ = new byte[fault.AllocateMemoryMB * 1024 * 1024];
           }

           return await action();
       }
   }

   public class FaultConfiguration
   {
       public Exception Exception { get; set; }
       public double FailureRate { get; set; } = 1.0;
       public int DelayMs { get; set; }
       public int AllocateMemoryMB { get; set; }
       public bool SimulateInfiniteLoop { get; set; }
       public bool SimulateConnectionLeak { get; set; }
   }
   ```

4. **Write Fault Injection Tests**:
   ```csharp
   public class FaultInjectionTests
   {
       [Fact]
       public async Task UnhandledException_DoesNotCrashProcess()
       {
           var testHost = new MultiTenantTestHost();
           var injector = new FaultInjector();

           injector.ConfigureFault("TexasClaimProcessor", new FaultConfiguration
           {
               Exception = new InvalidOperationException("Simulated crash"),
               FailureRate = 1.0
           });

           // Extension fails
           await Assert.ThrowsAsync<InvalidOperationException>(
               () => testHost.ProcessClaimAsync("TenantA", CreateTestClaim()));

           // But process still works for other tenants
           var result = await testHost.ProcessClaimAsync("TenantB", CreateTestClaim());
           Assert.True(result.Success);
       }

       [Fact]
       public async Task MemoryLeak_DoesNotExhaustProcess()
       {
           var testHost = new MultiTenantTestHost();
           var baselineMemory = GC.GetTotalMemory(true);

           // Extension with memory leak
           var leakyExtension = CreateMemoryLeakingExtension();

           // Execute 100 times
           for (int i = 0; i < 100; i++)
           {
               await testHost.ExecuteExtensionAsync("TenantA", leakyExtension);

               // Force GC to see if memory is released
               if (i % 10 == 0)
                   GC.Collect(GC.MaxGeneration, GCCollectionMode.Forced, true);
           }

           var currentMemory = GC.GetTotalMemory(false);
           var memoryIncrease = currentMemory - baselineMemory;

           // Memory increase should be bounded (< 500MB)
           Assert.True(memoryIncrease < 500 * 1024 * 1024,
               $"Memory leak detected: {memoryIncrease / 1024 / 1024}MB increase");
       }

       [Fact]
       public async Task ConnectionLeak_DoesNotExhaustPool()
       {
           var testHost = new MultiTenantTestHost();
           var connectionMonitor = new ConnectionPoolMonitor();

           // Extension that leaks connections
           var leakyExtension = CreateConnectionLeakingExtension();

           // Execute multiple times
           for (int i = 0; i < 50; i++)
           {
               await testHost.ExecuteExtensionAsync("TenantA", leakyExtension);
           }

           // Connection pool should not be exhausted
           var availableConnections = connectionMonitor.GetAvailableConnections();
           Assert.True(availableConnections > 0,
               "Connection pool exhausted due to leaks");
       }
   }
   ```

