#### Phase 3: Security and Data Leak Testing

5. **Create Tenant Isolation Validator**:
   ```csharp
   public class TenantIsolationValidator
   {
       private readonly TestDbContext _context;

       public async Task<IsolationTestResult> ValidateTenantIsolationAsync(
           string tenantId, Func<Task> extensionAction)
       {
           var result = new IsolationTestResult { TenantId = tenantId };

           // Record queries executed
           var queryLogger = new QueryLogger();
           _context.EnableQueryLogging(queryLogger);

           try
           {
               await extensionAction();

               // Analyze queries for tenant filter bypass
               var queries = queryLogger.GetQueries();
               foreach (var query in queries)
               {
                   if (query.Contains("IgnoreQueryFilters"))
                       result.Violations.Add("Query filter bypass detected");

                   if (!query.Contains($"TenantId = '{tenantId}'"))
                       result.Violations.Add($"Query missing tenant filter: {query}");
               }
           }
           finally
           {
               _context.DisableQueryLogging();
           }

           result.IsValid = !result.Violations.Any();
           return result;
       }
   }
   ```

6. **Write Cross-Tenant Access Tests**:
   ```csharp
   public class CrossTenantAccessTests
   {
       [Fact]
       public async Task Extension_CannotQueryOtherTenantData()
       {
           var testHost = new MultiTenantTestHost();

           // Seed data for two tenants
           await testHost.SeedTenantDataAsync("TenantA", claims: 100);
           await testHost.SeedTenantDataAsync("TenantB", claims: 50);

           // Extension for Tenant A
           using var scope = testHost.CreateTenantScope("TenantA");
           var context = scope.GetService<TestDbContext>();

           // Query should only return Tenant A's data
           var claims = await context.Claims.ToListAsync();

           Assert.Equal(100, claims.Count);
           Assert.All(claims, c => Assert.Equal("TenantA", c.TenantId));
       }

       [Fact]
       public async Task Extension_CannotBypassTenantFilter()
       {
           var testHost = new MultiTenantTestHost();
           var validator = new TenantIsolationValidator();

           await testHost.SeedTenantDataAsync("TenantA", claims: 10);
           await testHost.SeedTenantDataAsync("TenantB", claims: 20);

           using var scope = testHost.CreateTenantScope("TenantA");

           // Malicious extension trying to bypass filter
           var result = await validator.ValidateTenantIsolationAsync("TenantA", async () =>
           {
               var context = scope.GetService<TestDbContext>();
               // Attempt bypass
               var allClaims = await context.Claims.IgnoreQueryFilters().ToListAsync();
           });

           Assert.False(result.IsValid);
           Assert.Contains("Query filter bypass detected", result.Violations);
       }

       [Fact]
       public async Task Extension_CannotModifyTenantContext()
       {
           var testHost = new MultiTenantTestHost();

           using var scope = testHost.CreateTenantScope("TenantA");
           var tenantContext = scope.GetService<ITenantContext>();

           // Record initial tenant
           var originalTenant = tenantContext.GetCurrentTenantId();

           // Extension attempts to change tenant
           try
           {
               tenantContext.SetTenant("TenantB");
           }
           catch (InvalidOperationException)
           {
               // Expected: tenant context is read-only after initialization
           }

           // Verify tenant unchanged
           Assert.Equal(originalTenant, tenantContext.GetCurrentTenantId());
       }
   }
   ```

7. **Create Chaos Test Suite**:
   ```csharp
   public class ChaosTestSuite
   {
       [Fact]
       public async Task ChaosTest_RandomFailures_SystemRemainsStable()
       {
           var chaos = new ChaosEngine()
               .WithFailureRate(0.20) // 20% failure rate
               .WithRandomLatency(10, 500)
               .WithMemoryPressure(probabilityPercent: 10);

           var testHost = new MultiTenantTestHost(chaos);
           var tenants = CreateTenants(10);

           // Execute 1000 operations
           var tasks = new List<Task<OperationResult>>();
           for (int i = 0; i < 1000; i++)
           {
               var tenant = tenants[i % tenants.Count];
               tasks.Add(testHost.ProcessClaimAsync(tenant, CreateRandomClaim()));
           }

           var results = await Task.WhenAll(tasks);

           // Analyze results
           var successRate = results.Count(r => r.Success) / (double)results.Length;
           Assert.InRange(successRate, 0.75, 0.85); // ~80% success expected

           // Verify no cascading failures (all tenants should have some successes)
           foreach (var tenant in tenants)
           {
               var tenantResults = results.Where(r => r.TenantId == tenant);
               var tenantSuccess = tenantResults.Count(r => r.Success) / (double)tenantResults.Count();
               Assert.True(tenantSuccess > 0.50,
                   $"{tenant} had cascading failure: {tenantSuccess:P} success rate");
           }
       }
   }
   ```

