        // Configure resource monitoring
        host.ConfigureResourceMonitoring(options =>
        {
            options.TrackMemoryUsage = true;
            options.TrackConnectionPoolUsage = true;
            options.TrackExecutionTime = true;
            options.AlertOnExcessiveUsage = true;
        });

        return host;
    }
}
