### Real-World Example 1: Extension Failure Containment

**Context**: Texas claims extension throws unexpected NullReferenceException during processing. Must verify exception doesn't crash process or affect other tenants.

**Test Implementation**:

```csharp
public class TexasExtensionFailureContainmentTest
{
    [Fact]
    public async Task TexasExtension_Exception_DoesNotAffectOtherTenants()
    {
        // Arrange: Multi-tenant test environment
        var testHost = new MultiTenantTestHost();

        // Seed data for three tenants
        await testHost.SeedTenantDataAsync("Texas", claims: 100);
        await testHost.SeedTenantDataAsync("Florida", claims: 50);
        await testHost.SeedTenantDataAsync("California", claims: 75);

        // Configure fault injection for Texas only
        var faultInjector = new FaultInjector();
        faultInjector.ConfigureFault("TexasClaimProcessor", new FaultConfiguration
        {
            Exception = new NullReferenceException("Simulated extension bug"),
            FailureRate = 1.0 // Always fail
        });
        testHost.UseFaultInjector(faultInjector);

        // Act: Process claims for all tenants simultaneously
        var texasClaim = CreateTestClaim();
        var floridaClaim = CreateTestClaim();
        var californiaClaim = CreateTestClaim();

        var texasTask = testHost.ProcessClaimAsync("Texas", texasClaim);
        var floridaTask = testHost.ProcessClaimAsync("Florida", floridaClaim);
        var californiaTask = testHost.ProcessClaimAsync("California", californiaClaim);

        // Assert: Texas fails but others succeed
        var texasException = await Assert.ThrowsAsync<NullReferenceException>(() => texasTask);
        Assert.Contains("Simulated extension bug", texasException.Message);

        var floridaResult = await floridaTask;
        Assert.True(floridaResult.Success, "Florida should process successfully");

        var californiaResult = await californiaTask;
        Assert.True(californiaResult.Success, "California should process successfully");

        // Verify process health
        Assert.True(testHost.IsProcessHealthy());
        Assert.True(testHost.CanAcceptNewRequests());
    }

    [Fact]
    public async Task TexasExtension_InfiniteLoop_TerminatedByTimeout()
    {
        var testHost = new MultiTenantTestHost();

        // Extension with infinite loop
        var config = new FaultConfiguration
        {
            SimulateInfiniteLoop = true
        };
        var faultInjector = new FaultInjector();
        faultInjector.ConfigureFault("TexasClaimProcessor", config);
        testHost.UseFaultInjector(faultInjector);

        // Set timeout
        var timeoutMs = 2000;
        using var cts = new CancellationTokenSource(timeoutMs);

        // Execute with timeout
        var stopwatch = Stopwatch.StartNew();
        await Assert.ThrowsAsync<OperationCanceledException>(
            () => testHost.ProcessClaimAsync("Texas", CreateTestClaim(), cts.Token));
        stopwatch.Stop();

        // Verify terminated around timeout duration
        Assert.InRange(stopwatch.ElapsedMilliseconds, timeoutMs - 500, timeoutMs + 500);

        // Verify other tenants still work
        var floridaResult = await testHost.ProcessClaimAsync("Florida", CreateTestClaim());
        Assert.True(floridaResult.Success);
    }
}
```

