### Real-World Example 2: Resource Exhaustion Prevention

**Context**: Florida extension has memory leak that gradually consumes memory over repeated executions. Must verify resource limits prevent exhaustion.

**Test Implementation**:

```csharp
public class ResourceExhaustionPreventionTest
{
    [Fact]
    public async Task FloridaExtension_MemoryLeak_ContainedByLimits()
    {
        // Configure resource limits
        var limiter = new ResourceLimiter
        {
            MaxMemoryPerExtensionMB = 100,
            MaxExecutionTimeSeconds = 5,
            AlertThresholdPercent = 80
        };

        var testHost = new MultiTenantTestHost(limiter);
        var monitor = new ResourceMonitor();

        // Create extension that leaks 10MB per execution
        var leakyExtension = new LeakyExtension(leakSizeMB: 10);

        var executionResults = new List<ExecutionResult>();

        // Execute extension 15 times (would leak 150MB without limits)
        for (int i = 0; i < 15; i++)
        {
            monitor.StartTracking($"Execution-{i}");

            try
            {
                var result = await testHost.ExecuteExtensionAsync(
                    "Florida",
                    leakyExtension,
                    cancellationToken: CancellationToken.None);

                executionResults.Add(new ExecutionResult
                {
                    ExecutionNumber = i,
                    Success = true,
                    MemoryUsedMB = monitor.GetCurrentMemoryUsage()
                });
            }
            catch (ResourceLimitExceededException ex)
            {
                executionResults.Add(new ExecutionResult
                {
                    ExecutionNumber = i,
                    Success = false,
                    ErrorMessage = ex.Message,
                    MemoryUsedMB = monitor.GetCurrentMemoryUsage()
                });
            }
            finally
            {
                monitor.StopTracking($"Execution-{i}");
            }
        }

        // Analyze results
        var successfulExecutions = executionResults.Count(r => r.Success);
        var failedExecutions = executionResults.Count(r => !r.Success);
        var maxMemoryUsed = executionResults.Max(r => r.MemoryUsedMB);

        // Assertions
        Assert.True(successfulExecutions < 15,
            "Extension should be terminated before all executions complete");
        Assert.True(failedExecutions > 0,
            "Resource limit should trigger failures");
        Assert.True(maxMemoryUsed <= 110, // 100MB limit + 10% tolerance
            $"Memory usage exceeded limit: {maxMemoryUsed}MB");

        // Verify process still healthy
        Assert.True(testHost.IsProcessHealthy());
        Assert.True(testHost.CanAcceptNewRequests());

        // Verify other tenants unaffected
        var texasResult = await testHost.ProcessClaimAsync("Texas", CreateTestClaim());
        Assert.True(texasResult.Success, "Texas tenant should be unaffected");
    }

    [Fact]
    public async Task ConnectionLeak_PreventedByPoolMonitoring()
    {
        var testHost = new MultiTenantTestHost();
        var connectionMonitor = new ConnectionPoolMonitor();

        // Extension that leaks database connections
        var leakyExtension = new ConnectionLeakingExtension();

        var baselineConnections = connectionMonitor.GetAvailableConnections();

        // Execute extension 20 times (leaks 1 connection each time)
        for (int i = 0; i < 20; i++)
        {
            try
            {
                await testHost.ExecuteExtensionAsync("California", leakyExtension);
            }
            catch (ConnectionPoolExhaustedException ex)
            {
                // Expected when pool exhausted
                Console.WriteLine($"Connection pool exhausted at execution {i}");
                break;
            }
        }

        var remainingConnections = connectionMonitor.GetAvailableConnections();
        var leakedConnections = baselineConnections - remainingConnections;

        // Verify leak detected
        Assert.True(leakedConnections > 0, "Connection leak should be detected");

        // Force connection cleanup
        await testHost.ForceConnectionCleanupAsync();

        var connectionsAfterCleanup = connectionMonitor.GetAvailableConnections();
        Assert.True(connectionsAfterCleanup > remainingConnections,
            "Cleanup should recover leaked connections");

        // Verify system recovered
        var result = await testHost.ProcessClaimAsync("California", CreateTestClaim());
        Assert.True(result.Success, "System should recover after cleanup");
    }
}

public class LeakyExtension : IExtension
{
    private readonly int _leakSizeMB;
    private readonly List<byte[]> _leak = new();

    public LeakyExtension(int leakSizeMB)
    {
        _leakSizeMB = leakSizeMB;
    }

    public Task<ExtensionResult> ExecuteAsync(ExtensionContext context)
    {
        // Intentionally leak memory
        _leak.Add(new byte[_leakSizeMB * 1024 * 1024]);

        return Task.FromResult(ExtensionResult.Success());
    }
}
